async function yamlDialog(importing){$('yaml-error').textContent='';try{$('yaml').value=stack()?await api(`/api/export/${encodeURIComponent(ui.fixture)}/${ui.layer}`):'name: New stack\nstack:\n  Create.Color.Color:\n    Color: "#72dec2"\n';$('yaml-dialog').showModal();$('yaml-apply').hidden=!importing;}catch(error){status(error.message,true);}}
$('import').onclick=()=>yamlDialog(true);$('export').onclick=()=>yamlDialog(false);$('yaml-apply').onclick=async()=>{try{await api('/api/import',{fixture:ui.fixture,layer:ui.layer,yaml:$('yaml').value,expected_revision:ui.data.snapshot.revision});$('yaml-dialog').close();ui.driver=null;ui.node=0;await refresh(true);status('ScenicScript validated and applied');}catch(error){$('yaml-error').textContent=error.message;}};
$('yaml-download').onclick=()=>{const url=URL.createObjectURL(new Blob([$('yaml').value],{type:'text/yaml'})),a=el('a');a.href=url;a.download='stack.scnq.yaml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('apply').onclick=()=>{const select=$('apply-target');while(select.options.length>2)select.remove(2);for(const group of new Set(ui.data.project.fixtures.flatMap(f=>f.groups))){const o=el('option',`Group: ${group}`);o.value=`group:${group}`;select.append(o);}$('apply-dialog').showModal();};
$('apply-confirm').onclick=async()=>{const mode=$('apply-target').value,targets=ui.data.project.fixtures.filter(f=>mode==='all'||mode==='selection'&&ui.selected.has(f.id)||mode.startsWith('group:')&&f.groups.includes(mode.slice(6)));if(!targets.length){status('No target fixtures selected',true);return;}await command({type:'apply_content',entries:targets.map(f=>({fixture:f.id,layer:ui.layer,stack:stack()}))});$('apply-dialog').close();};
$('content-load').onclick=async()=>{try{await api('/api/content/load',{name:$('content-name').value,group:$('content-group').value||null,expected_revision:ui.data.snapshot.revision});$('apply-dialog').close();await refresh(true);}catch(error){status(error.message,true);}};
$('connect').onclick=async()=>{const value=prompt('Server API token (leave empty for local server)',ui.token);if(value===null)return;ui.token=value;sessionStorage.setItem('schema-token',value);try{await loadCatalog();await refresh(true);}catch(error){status(error.message,true);}};
function zoom(delta){ui.scale=Math.max(1e-6,Math.min(16,ui.scale*delta));renderTree();}
$('zoom-in').onclick=()=>zoom(1.2);$('zoom-out').onclick=()=>zoom(1/1.2);$('fit').onclick=()=>{const r=root();if(!r)return;const canvas=$('canvas'),fitted=SchemaStackLayout.fit(layout(r),{width:canvas.clientWidth,height:canvas.clientHeight});ui.scale=fitted.scale;ui.pan=fitted.pan;canvas.scrollTop=0;canvas.scrollLeft=0;renderTree();canvas.scrollTop=0;canvas.scrollLeft=0;};
$('canvas').onwheel=e=>{e.preventDefault();zoom(e.deltaY<0?1.08:1/1.08);};$('canvas').onpointerdown=e=>{if(e.target.closest('.block,button'))return;ui.drag={kind:'pan',x:e.clientX,y:e.clientY,original:{...ui.pan}};$('canvas').setPointerCapture(e.pointerId);};$('canvas').onpointermove=e=>{if(ui.drag?.kind==='pan'){ui.pan={x:ui.drag.original.x+e.clientX-ui.drag.x,y:ui.drag.original.y+e.clientY-ui.drag.y};transform();}};$('canvas').onpointerup=()=>{if(ui.drag?.kind==='pan')ui.drag=null;};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.move){e.preventDefault();clearBlockDrag();return;}if(e.target.matches('input,textarea,select')||e.target.isContentEditable||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();command({type:e.shiftKey?'redo':'undo'});}else if(workspaceUI&&['Delete','Backspace','f','F','+','-'].includes(e.key)&&((e.target.closest('.workspace-panel')?.dataset.view||workspaceUI.panel()?.view)!=='stack'))return;else if(e.key==='f'||e.key==='F')$('fit').click();else if(e.key==='+')zoom(1.2);else if(e.key==='-')zoom(1/1.2);else if((e.key==='Delete'||e.key==='Backspace')&&selected()){e.preventDefault();openNodeDelete(ui.node);}else if(e.key===' '){e.preventDefault();$('pause').click();}});
(async()=>{try{await loadCatalog();await refresh(true);$('fit').click();status(`Engine connected · ${ui.data?.project.output.enabled?'live DMX output':'capture only'} · scene and stack editing ready`);}catch(error){status(error.message,true);}setInterval(()=>refresh(),100);})();

$('save-layer-content').onclick=async()=>{try{const name=prompt('Content snapshot name','partial');if(!name)return;await api('/api/project/save',{name,scope:'content',fixtures:[...ui.selected],layer:ui.layer});status('Saved selected fixture/layer content; layout untouched');}catch(error){status(error.message,true);}};
$('save-layout').onclick=async()=>{try{const name=prompt('Layout snapshot name','init');if(!name)return;await api('/api/project/save',{name,scope:'layout'});status('Layout saved; content untouched');}catch(error){status(error.message,true);}};
function renderCurveEditor(n,box){
 const keys=['P0','P1','P2','P3'],defaults=ui.catalog.find(b=>b.key===n.behavior).defaults;
 const points=keys.map(key=>[...(n.properties[key]||defaults[key])]);
 const minX=Math.min(...points.map(p=>p[0]))-1,maxX=Math.max(...points.map(p=>p[0]))+1,minZ=Math.min(...points.map(p=>p[2]))-1,maxZ=Math.max(...points.map(p=>p[2]))+1;
 const project=p=>[12+(p[0]-minX)/(maxX-minX)*232,12+(p[2]-minZ)/(maxZ-minZ)*146];
 const view=svg('svg',{viewBox:'0 0 256 170',class:'curve-editor','aria-label':'Bézier path in X/Z plane'});
 const guide=svg('path',{class:'curve-guide'}),path=svg('path',{class:'curve-path'}),live=svg('circle',{r:4,class:'curve-live'});view.append(guide,path);
 const handles=points.map((point,index)=>{const handle=svg('circle',{r:index===0||index===3?6:5,class:'curve-handle','data-point':keys[index],tabindex:0,role:'slider','aria-label':`${keys[index]} X/Z curve handle`,'aria-valuetext':point.join(', ')});const title=svg('title');title.textContent=`${keys[index]} · drag X/Z, arrow keys nudge, vector field edits Y`;handle.append(title);view.append(handle);return handle;});
 function draw(){const p=points.map(project);path.setAttribute('d',`M${p[0]} C${p[1]} ${p[2]} ${p[3]}`);guide.setAttribute('d',`M${p[0]} L${p[1]} M${p[2]} L${p[3]}`);handles.forEach((handle,i)=>{handle.setAttribute('cx',p[i][0]);handle.setAttribute('cy',p[i][1]);handle.setAttribute('aria-valuetext',points[i].join(', '));});}
 let dragging=null;
 const commit=index=>command({type:'set_property',fixture:ui.fixture,layer:ui.layer,node:n.id,key:keys[index],value:points[index].map(v=>Math.round(v*1000)/1000)});
 handles.forEach((handle,index)=>{handle.onpointerdown=event=>{event.preventDefault();dragging={index,before:[...points[index]]};handle.setPointerCapture(event.pointerId);};handle.onpointermove=event=>{if(dragging?.index!==index)return;const local=new DOMPoint(event.clientX,event.clientY).matrixTransform(view.getScreenCTM().inverse());points[index][0]=minX+(Math.max(6,Math.min(250,local.x))-12)/232*(maxX-minX);points[index][2]=minZ+(Math.max(6,Math.min(164,local.y))-12)/146*(maxZ-minZ);draw();};handle.onpointerup=()=>{if(dragging?.index!==index)return;const before=dragging.before;dragging=null;if(points[index].some((v,i)=>Math.abs(v-before[i])>0.0005))commit(index);};handle.onpointercancel=handle.onlostpointercapture=()=>{if(dragging?.index===index){points[index]=dragging.before;dragging=null;draw();}};handle.onkeydown=event=>{if(event.key==='Escape'&&dragging){points[dragging.index]=dragging.before;dragging=null;draw();return;}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const amount=event.shiftKey?1:0.1;points[index][event.key==='ArrowLeft'||event.key==='ArrowRight'?0:2]+=['ArrowLeft','ArrowUp'].includes(event.key)?-amount:amount;draw();};handle.onkeyup=event=>{if(event.key.startsWith('Arrow'))commit(index);};});
 view.append(live);draw();ui.curveEditor={live,update:position=>{const p=project(position);live.setAttribute('cx',p[0]);live.setAttribute('cy',p[1]);},node:n.id,layer:ui.layer};
 const heading=el('h3','Bézier path','curve-heading'),caption=el('p','X / Z · drag handles or use arrow keys. Edit Y in the vector fields below.','curve-caption');box.append(heading,view,caption);
}

function renderValueCurveEditor(n,box){const target={fixture:ui.fixture,layer:ui.layer,node:n.id};let revision=ui.data.snapshot.revision;ui.valueCurve=SchemaBezier.mount(box,{properties:{...ui.catalog.find(b=>b.key===n.behavior)?.defaults,...n.properties},drivers:n.drivers,onCommit:async(key,value)=>{const ok=await command({type:'set_property',...target,key,value},revision);if(ok)revision=ui.data.snapshot.revision;return ok;}});}

SchemaScenePreview.configure({command,selected:()=>ui.fixture,getFrame:()=>ui.data,onSelect:id=>{if(ui.data)selectFixture(id,false);},onLoadProject:project=>command({type:'replace_project',project}),status});$('scene-preview').onclick=()=>SchemaScenePreview.open();
